"""R08: repair the existing flight shot's loss of city context.
Reuse the exact R07B finished ship, 20 km ring, buildings and render helpers.
No remodelling, no new ring, no replacement reference and no autogenerated art PASS.
Only ship/camera staging and the existing daylight rig change. The exterior shot
remains independently recoverable from its immutable input .blend and 1080p movie.
"""
import bpy,os,json,hashlib,math,ast,time,struct,resource
from pathlib import Path
from mathutils import Vector
