 root.animation_data_clear();root.rotation_euler=(0,0,0);target.location=(150,120,600)
 cameras=[]
 for name,offset,lens in [('R08_CROSS_CITY',(-1500,-650,-180),20),('R08_CITY_QUARTER',(-1300,-1000,-250),22)]:
  d=bpy.data.cameras.new(name);d.lens=lens;d.sensor_width=36;d.clip_start=.2;d.clip_end=60000;d.dof.use_dof=False
  o=bpy.data.objects.new(name,d);C['08_CAMERAS'].objects.link(o);o.parent=root;o.location=offset
