 for f in range(1,193):
  t=(f-1)/191;root.location=(-6000,3200-640*t,4400+20*t);root.keyframe_insert(data_path='location',frame=f)
 S.frame_start=1;S.frame_end=192;S.render.fps=24;S.camera=cameras[0]
 # Daylight fills the inhabited space; ship-only finishing materials are preserved.
 world=bpy.data.worlds.new('R08 inhabited daylight');world.use_nodes=True;nt=world.node_tree
 sky=nt.nodes.new('ShaderNodeTexSky');sky.sky_type='NISHITA';sky.sun_disc=False;sky.sun_elevation=.65;sky.sun_rotation=4.0;sky.dust_density=.35
 bg=nt.nodes.get('Background');bg.inputs['Strength'].default_value=.42;nt.links.new(sky.outputs['Color'],bg.inputs['Color']);S.world=world
 sun=bpy.data.objects['R07 soft directional daylight'];sun.data=sun.data.copy();sun.data.energy=2.6;sun.data.angle=.055;sun.data.color=(1,.90,.77)
 sun.rotation_euler=(Vector((-6000,3200,4500))-Vector((-4000,-9000,20000))).to_track_quat('-Z','Y').to_euler()
 for name,power in [('R07 large reflected sky aperture',16000000),('R07 lower reflected city fill',4000000),('R07B Finish / rear edge card',18000000)]:
  o=bpy.data.objects[name];o.data=o.data.copy();o.data.energy=power
 for n in S.node_tree.nodes:
  if n.bl_idname=='CompositorNodeMapRange':n.inputs['From Min'].default_value=2200;n.inputs['From Max'].default_value=24000;n.inputs['To Max'].default_value=.14
  elif n.bl_idname=='CompositorNodeMixRGB':n.inputs[2].default_value=(.30,.42,.54,1)
 S.view_settings.view_transform='AgX';S.view_settings.look='AgX - Medium High Contrast';S.view_settings.exposure=-.12
 checks=[];S.render.resolution_x=1280;S.render.resolution_y=720
